#!/usr/bin/env bash
# nvidia/nodewright v0.19.0 - base variant: default
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/nvidia-nodewright-v0-19-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the default base variant into ./nvidia-nodewright-v0-19-0-default"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/nvidia-nodewright:v0.19.0@sha256:58195953ff73a8e8b55b92b44504655b0cbfcee1b1196ac7730776c244136358 --base default --work-dir ./nvidia-nodewright-v0-19-0-default --non-interactive --namespace nodewright

say "Read what was rendered; nothing has touched the cluster yet"
ls ./nvidia-nodewright-v0-19-0-default/out/manifests

wait_for_crd() {
  crd_name="$1"
  deadline=$(( $(date +%s) + 180 ))
  until kubectl get "crd/${crd_name}" >/dev/null 2>&1; do
    if [ "$(date +%s)" -ge "$deadline" ]; then
      printf "CRD %s did not appear within 180 seconds.\n" "$crd_name" >&2
      return 1
    fi
    sleep 2
  done
  kubectl wait --for=condition=Established --timeout=120s "crd/${crd_name}"
}

say "Ensure the nodewright namespace exists"
kubectl create namespace nodewright --dry-run=client -o yaml | kubectl apply -f -

say "Check 4 CRDs included with this package"
missing_crds=0
if ! kubectl get crd/deploymentpolicies.nodewright.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/deploymentpolicies.skyhook.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/nodewrights.nodewright.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/skyhooks.skyhook.nvidia.com >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  kubectl apply --server-side -f ./nvidia-nodewright-v0-19-0-default/package/prerequisites/target-facts/default-crds.yaml
else
  say "The required CRDs already exist; leave them under their current owner"
fi
wait_for_crd deploymentpolicies.nodewright.nvidia.com
wait_for_crd deploymentpolicies.skyhook.nvidia.com
wait_for_crd nodewrights.nodewright.nvidia.com
wait_for_crd skyhooks.skyhook.nvidia.com

if [ -d ./nvidia-nodewright-v0-19-0-default/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./nvidia-nodewright-v0-19-0-default/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./nvidia-nodewright-v0-19-0-default/out/manifests

say "Done. The cluster received exactly the files in ./nvidia-nodewright-v0-19-0-default/out, with the packaged lifecycle steps checked."
